import { Icon } from "@/registry/erbium/ui/icon";

import { Bubble, BubbleContent, BubbleReactions } from "@/registry/erbium/ui/bubble";
import { Button } from "@/registry/erbium/ui/button";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/registry/erbium/ui/tooltip";

export function BubbleTooltipDemo() {
  return (
    <div className="flex w-full max-w-sm flex-col gap-group py-12">
      <Bubble variant="secondary">
        <BubbleContent>Did you remove the stale route?</BubbleContent>
      </Bubble>
      <Bubble align="end">
        <BubbleContent>Yes, removed it from the registry.</BubbleContent>
        <BubbleReactions>
          <Tooltip>
            <TooltipTrigger render={<Button variant="ghost" size="icon-xs" />}>
              <Icon name="check" />
            </TooltipTrigger>
            <TooltipContent>Read on Jan 5, 2026 at 4:32 PM</TooltipContent>
          </Tooltip>
        </BubbleReactions>
      </Bubble>
    </div>
  );
}

import { BubbleTooltipDemo } from "../examples/bubble-tooltip";

const Example = () => <BubbleTooltipDemo />;

export default Example;
